const keywords=new Set(['type','enum','const','minimum','maximum','minLength','maxLength','pattern','items','uniqueItems','minItems','maxItems','anyOf','not']);
function primitive(d){if(Array.isArray(d))return d.map(primitive);if(d&&typeof d==='object')return Object.fromEntries(Object.entries(d).filter(([k])=>keywords.has(k)).map(([k,x])=>[k,(k==='anyOf'||k==='items'||k==='not')?primitive(x):x]));return d;}
